<div class="heading"><div><h1>Member administration</h1><p>Create and manage local member accounts.</p></div><a class="button secondary" href="/admin/mailboxes">Mailbox administration</a></div>
<?php if($error): ?><p class="alert" role="alert"><?= htmlspecialchars($error) ?></p><?php endif; ?>
<?php if($notice): ?><p class="notice" role="status"><?= htmlspecialchars($notice) ?></p><?php endif; ?>
<section class="panel"><h2>Create member</h2><form method="post" action="/admin/members" class="grid"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><label>Email<input type="email" name="email" maxlength="254" autocomplete="off" required></label><label>Display name<input name="display_name" maxlength="120" required></label><label>Initial password<input type="password" name="password" minlength="14" maxlength="1024" autocomplete="new-password" required><small>At least 14 characters.</small></label><div><button type="submit">Create member</button></div></form></section>
<section class="panel"><h2>Accounts</h2><div class="table-wrap"><table><thead><tr><th>Email</th><th>Name</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><?= htmlspecialchars($m['email']) ?></td><td><?= htmlspecialchars($m['display_name']) ?></td><td><?= htmlspecialchars($m['role']) ?></td><td><?= htmlspecialchars($m['status']) ?></td><td><?php if($m['role']==='member'): ?><form method="post" action="/admin/members/<?= (int)$m['id'] ?>/status"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="status" value="<?= $m['status']==='active'?'suspended':'active' ?>"><button class="small <?= $m['status']==='active'?'danger':'secondary' ?>" type="submit"><?= $m['status']==='active'?'Suspend':'Activate' ?></button></form><?php else: ?><span class="muted">Administrator</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
